package com.tradingplatform.market;
import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*; import com.fasterxml.jackson.databind.ObjectMapper; import com.tradingplatform.persistence.*; import org.junit.jupiter.api.Test;
class InstrumentImportServiceTest { @Test void importsAndNormalizesOfficialJson(){var repo=mock(InstrumentCatalogRepository.class);when(repo.existsById("NSE_EQ|INE")).thenReturn(false);var service=new InstrumentImportService(repo,new ObjectMapper(),"");var report=service.importJson(new ObjectMapper().createArrayNode().addObject().put("instrument_key","NSE_EQ|INE").put("segment","NSE_EQ").put("exchange","NSE").put("instrument_type","EQ").put("trading_symbol","tcs").put("name","TCS"));assertEquals(1,report.inserted());verify(repo).save(argThat(x->x.symbol.equals("TCS")));} @Test void skipsMalformedRecord(){var repo=mock(InstrumentCatalogRepository.class);var service=new InstrumentImportService(repo,new ObjectMapper(),"");assertEquals(1,service.importJson(new ObjectMapper().createArrayNode().addObject().put("segment","NSE_EQ")).skipped());verifyNoInteractions(repo);} }
